-- =============================================================================
-- Craft BD — Core schema
-- =============================================================================
-- Relational model for the Craft BD marketplace:
--   accounts & roles, artisan studios, craft catalogue, cultural storytelling,
--   provenance certificates, commerce, custom orders, and moderated reviews.
--
-- Conventions:
--   * Primary keys are UUIDs generated by Postgres (gen_random_uuid).
--   * Money is stored in BDT as numeric(12, 2).
--   * Public catalogue data is filtered by RLS; private data is owner-scoped.
--   * Timestamps are timezone-aware and default to now().
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Enums
-- -----------------------------------------------------------------------------
create type public.user_role as enum ('customer', 'artisan', 'admin');

create type public.artisan_status as enum ('pending', 'approved', 'suspended');

create type public.product_status as enum ('draft', 'published', 'archived');

create type public.order_status as enum (
  'pending',
  'processing',
  'shipped',
  'delivered',
  'cancelled'
);

create type public.payment_status as enum ('unpaid', 'paid', 'refunded');

create type public.custom_order_status as enum (
  'submitted',
  'quoted',
  'approved',
  'declined',
  'in_production',
  'quality_check',
  'dispatched',
  'completed',
  'cancelled'
);

create type public.certificate_status as enum ('active', 'revoked');

create type public.review_status as enum ('pending', 'published', 'flagged', 'removed');

create type public.journey_stage as enum (
  'raw_materials',
  'design',
  'making',
  'finishing',
  'quality_check',
  'final_product'
);

create type public.bd_division as enum (
  'barishal',
  'chattogram',
  'dhaka',
  'khulna',
  'mymensingh',
  'rajshahi',
  'rangpur',
  'sylhet'
);

-- -----------------------------------------------------------------------------
-- Shared helpers
-- -----------------------------------------------------------------------------
create or replace function public.set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

-- Admin authorization comes from the signed JWT's app_metadata, which can only
-- be written with the service-role key. Profile.role is display data, not the
-- security boundary.
create or replace function public.is_admin()
returns boolean
language sql
stable
security invoker
set search_path = ''
as $$
  select coalesce((auth.jwt() -> 'app_metadata' ->> 'role') = 'admin', false);
$$;

-- -----------------------------------------------------------------------------
-- Accounts
-- -----------------------------------------------------------------------------
create table public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  email text,
  full_name text not null default '',
  phone text,
  avatar_url text,
  role public.user_role not null default 'customer',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

comment on table public.profiles is
  'Marketplace account profile. One row per Supabase Auth user.';

create unique index profiles_email_key
  on public.profiles (lower(email))
  where email is not null;

create index profiles_role_idx on public.profiles (role);

create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  requested_role public.user_role;
begin
  requested_role := case
    when new.raw_app_meta_data ->> 'role' in ('customer', 'artisan', 'admin')
      then (new.raw_app_meta_data ->> 'role')::public.user_role
    else 'customer'::public.user_role
  end;

  insert into public.profiles (id, email, full_name, avatar_url, role)
  values (
    new.id,
    new.email,
    coalesce(
      nullif(new.raw_user_meta_data ->> 'full_name', ''),
      nullif(new.raw_user_meta_data ->> 'name', ''),
      split_part(coalesce(new.email, 'Craft BD member'), '@', 1)
    ),
    nullif(new.raw_user_meta_data ->> 'avatar_url', ''),
    requested_role
  )
  on conflict (id) do nothing;

  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

create or replace function public.protect_profile_role()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if new.role is distinct from old.role
     and (select auth.uid()) is not null
     and not public.is_admin() then
    raise exception 'Only administrators can change account roles';
  end if;

  return new;
end;
$$;

create trigger profiles_protect_role
  before update on public.profiles
  for each row execute function public.protect_profile_role();

create trigger profiles_set_updated_at
  before update on public.profiles
  for each row execute function public.set_updated_at();

-- -----------------------------------------------------------------------------
-- Taxonomy
-- -----------------------------------------------------------------------------
create table public.categories (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  slug text not null unique,
  description text not null default '',
  image_url text,
  icon text,
  is_active boolean not null default true,
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint categories_slug_format check (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'),
  constraint categories_sort_order_positive check (sort_order >= 0)
);

create trigger categories_set_updated_at
  before update on public.categories
  for each row execute function public.set_updated_at();

-- -----------------------------------------------------------------------------
-- Artisans
-- -----------------------------------------------------------------------------
create table public.artisans (
  id uuid primary key default gen_random_uuid(),
  profile_id uuid unique references public.profiles (id) on delete set null,
  display_name text not null,
  slug text not null unique,
  workshop_name text,
  craft_specialization text not null,
  primary_category_id uuid references public.categories (id) on delete set null,
  region public.bd_division not null,
  district text not null,
  years_of_experience integer not null default 0,
  biography text not null default '',
  story_video_url text,
  avatar_url text,
  cover_image_url text,
  languages text[] not null default array['Bangla']::text[],
  status public.artisan_status not null default 'pending',
  is_featured boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint artisans_slug_format check (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'),
  constraint artisans_experience_range check (years_of_experience between 0 and 80)
);

comment on table public.artisans is
  'Public artisan studio profile, optionally linked to a login account.';

create index artisans_status_idx on public.artisans (status);
create index artisans_region_idx on public.artisans (region);
create index artisans_category_idx on public.artisans (primary_category_id);
create index artisans_featured_idx on public.artisans (is_featured)
  where status = 'approved';

create or replace function public.protect_artisan_fields()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if (new.status is distinct from old.status
      or new.is_featured is distinct from old.is_featured)
     and (select auth.uid()) is not null
     and not public.is_admin() then
    raise exception 'Only administrators can change artisan status or featuring';
  end if;

  return new;
end;
$$;

create trigger artisans_protect_status
  before update on public.artisans
  for each row execute function public.protect_artisan_fields();

create trigger artisans_set_updated_at
  before update on public.artisans
  for each row execute function public.set_updated_at();

-- -----------------------------------------------------------------------------
-- Products
-- -----------------------------------------------------------------------------
create table public.products (
  id uuid primary key default gen_random_uuid(),
  artisan_id uuid not null references public.artisans (id) on delete restrict,
  category_id uuid not null references public.categories (id) on delete restrict,
  title text not null,
  slug text not null unique,
  short_description text not null default '',
  description text not null default '',
  price_bdt numeric(12, 2) not null,
  compare_at_price_bdt numeric(12, 2),
  stock_quantity integer not null default 0,
  materials text[] not null default array[]::text[],
  dimensions text,
  weight_grams integer,
  care_instructions text,
  region public.bd_division not null,
  occasion_tags text[] not null default array[]::text[],
  gift_wrap_available boolean not null default true,
  status public.product_status not null default 'draft',
  is_featured boolean not null default false,
  published_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint products_slug_format check (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'),
  constraint products_price_positive check (price_bdt > 0),
  constraint products_compare_price_valid check (
    compare_at_price_bdt is null or compare_at_price_bdt > price_bdt
  ),
  constraint products_stock_non_negative check (stock_quantity >= 0),
  constraint products_weight_positive check (weight_grams is null or weight_grams > 0),
  constraint products_published_at_required check (
    status <> 'published' or published_at is not null
  )
);

comment on table public.products is
  'Catalogue item handmade by a single artisan studio.';

create index products_status_category_idx on public.products (status, category_id);
create index products_status_region_idx on public.products (status, region);
create index products_price_idx on public.products (price_bdt);
create index products_artisan_idx on public.products (artisan_id);
create index products_materials_idx on public.products using gin (materials);
create index products_occasions_idx on public.products using gin (occasion_tags);
create index products_featured_idx on public.products (is_featured)
  where status = 'published';

create or replace function public.protect_product_flags()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if new.is_featured is distinct from old.is_featured
     and (select auth.uid()) is not null
     and not public.is_admin() then
    raise exception 'Only administrators can feature products';
  end if;

  return new;
end;
$$;

create trigger products_protect_flags
  before update on public.products
  for each row execute function public.protect_product_flags();

create trigger products_set_updated_at
  before update on public.products
  for each row execute function public.set_updated_at();

create table public.product_images (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null references public.products (id) on delete cascade,
  url text not null,
  alt_text text not null default '',
  sort_order integer not null default 0,
  is_primary boolean not null default false,
  created_at timestamptz not null default now(),
  constraint product_images_sort_order_positive check (sort_order >= 0),
  constraint product_images_product_sort_key unique (product_id, sort_order)
);

create unique index product_images_one_primary_idx
  on public.product_images (product_id)
  where is_primary;

create index product_images_product_idx on public.product_images (product_id);

-- -----------------------------------------------------------------------------
-- Cultural storytelling
-- -----------------------------------------------------------------------------
create table public.craft_stories (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null unique references public.products (id) on delete cascade,
  title text not null,
  origin text not null,
  history text not null,
  traditional_uses text not null,
  materials_description text not null,
  cultural_meaning text not null,
  did_you_know text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create trigger craft_stories_set_updated_at
  before update on public.craft_stories
  for each row execute function public.set_updated_at();

create table public.craft_journeys (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null references public.products (id) on delete cascade,
  stage public.journey_stage not null,
  title text not null,
  description text not null,
  duration_label text,
  image_url text,
  sort_order smallint not null,
  created_at timestamptz not null default now(),
  constraint craft_journeys_sort_order_range check (sort_order between 1 and 6),
  constraint craft_journeys_product_stage_key unique (product_id, stage),
  constraint craft_journeys_product_order_key unique (product_id, sort_order)
);

create index craft_journeys_product_idx on public.craft_journeys (product_id, sort_order);

-- -----------------------------------------------------------------------------
-- Provenance certificates
-- -----------------------------------------------------------------------------
create table public.certificates (
  id uuid primary key default gen_random_uuid(),
  certificate_code text not null unique,
  product_id uuid not null unique references public.products (id) on delete cascade,
  artisan_id uuid not null references public.artisans (id) on delete restrict,
  issued_at date not null default current_date,
  certificate_payload jsonb not null,
  certificate_hash text not null,
  status public.certificate_status not null default 'active',
  revoked_at timestamptz,
  revocation_reason text,
  created_at timestamptz not null default now(),
  constraint certificates_code_format check (
    certificate_code ~ '^CBD-[A-Z]{3}-[0-9]{4}-[0-9]{4}$'
  ),
  constraint certificates_hash_format check (certificate_hash ~ '^[a-f0-9]{64}$'),
  constraint certificates_revocation_valid check (
    (status = 'active' and revoked_at is null)
    or (status = 'revoked' and revoked_at is not null)
  )
);

comment on table public.certificates is
  'Tamper-evident provenance record. The payload hash is recomputed on verification.';

create index certificates_artisan_idx on public.certificates (artisan_id);
create index certificates_status_idx on public.certificates (status);

-- -----------------------------------------------------------------------------
-- Commerce
-- -----------------------------------------------------------------------------
create table public.addresses (
  id uuid primary key default gen_random_uuid(),
  profile_id uuid not null references public.profiles (id) on delete cascade,
  label text not null default 'Home',
  recipient_name text not null,
  phone text not null,
  address_line1 text not null,
  address_line2 text,
  city text not null,
  district text not null,
  division public.bd_division not null,
  postal_code text,
  is_default boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index addresses_profile_idx on public.addresses (profile_id);

create unique index addresses_one_default_idx
  on public.addresses (profile_id)
  where is_default;

create trigger addresses_set_updated_at
  before update on public.addresses
  for each row execute function public.set_updated_at();

create table public.orders (
  id uuid primary key default gen_random_uuid(),
  order_number text not null unique,
  customer_id uuid not null references public.profiles (id) on delete restrict,
  status public.order_status not null default 'pending',
  payment_status public.payment_status not null default 'unpaid',
  subtotal_bdt numeric(12, 2) not null default 0,
  shipping_bdt numeric(12, 2) not null default 0,
  gift_wrap_bdt numeric(12, 2) not null default 0,
  total_bdt numeric(12, 2) generated always as (
    subtotal_bdt + shipping_bdt + gift_wrap_bdt
  ) stored,
  shipping_address jsonb not null,
  gift_message text,
  gift_wrap boolean not null default false,
  placed_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint orders_amounts_non_negative check (
    subtotal_bdt >= 0 and shipping_bdt >= 0 and gift_wrap_bdt >= 0
  )
);

create index orders_customer_idx on public.orders (customer_id, placed_at desc);
create index orders_status_idx on public.orders (status);

create trigger orders_set_updated_at
  before update on public.orders
  for each row execute function public.set_updated_at();

create table public.order_items (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null references public.orders (id) on delete cascade,
  product_id uuid references public.products (id) on delete set null,
  artisan_id uuid references public.artisans (id) on delete set null,
  product_title text not null,
  product_image_url text,
  unit_price_bdt numeric(12, 2) not null,
  quantity integer not null,
  line_total_bdt numeric(12, 2) generated always as (
    round(unit_price_bdt * quantity, 2)
  ) stored,
  gift_wrap boolean not null default false,
  created_at timestamptz not null default now(),
  constraint order_items_unit_price_non_negative check (unit_price_bdt >= 0),
  constraint order_items_quantity_positive check (quantity > 0)
);

create index order_items_order_idx on public.order_items (order_id);
create index order_items_product_idx on public.order_items (product_id);
create index order_items_artisan_idx on public.order_items (artisan_id);

create table public.custom_orders (
  id uuid primary key default gen_random_uuid(),
  request_code text not null unique,
  customer_id uuid not null references public.profiles (id) on delete cascade,
  artisan_id uuid not null references public.artisans (id) on delete restrict,
  category_id uuid references public.categories (id) on delete set null,
  product_type text not null,
  design_description text not null,
  color text,
  size text,
  material text,
  quantity integer not null default 1,
  reference_image_url text,
  custom_notes text,
  budget_min_bdt numeric(12, 2),
  budget_max_bdt numeric(12, 2),
  status public.custom_order_status not null default 'submitted',
  price_estimate_bdt numeric(12, 2),
  estimated_days integer,
  artisan_note text,
  customer_response_note text,
  responded_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint custom_orders_code_format check (request_code ~ '^CUS-[0-9]{4}-[0-9]{4}$'),
  constraint custom_orders_quantity_positive check (quantity > 0),
  constraint custom_orders_budget_valid check (
    budget_min_bdt is null
    or budget_max_bdt is null
    or budget_max_bdt >= budget_min_bdt
  ),
  constraint custom_orders_budget_non_negative check (
    (budget_min_bdt is null or budget_min_bdt >= 0)
    and (budget_max_bdt is null or budget_max_bdt >= 0)
  ),
  constraint custom_orders_estimate_non_negative check (
    price_estimate_bdt is null or price_estimate_bdt >= 0
  ),
  constraint custom_orders_estimated_days_positive check (
    estimated_days is null or estimated_days > 0
  )
);

create index custom_orders_customer_idx on public.custom_orders (customer_id, created_at desc);
create index custom_orders_artisan_idx on public.custom_orders (artisan_id, created_at desc);
create index custom_orders_status_idx on public.custom_orders (status);

create trigger custom_orders_set_updated_at
  before update on public.custom_orders
  for each row execute function public.set_updated_at();

create or replace function public.protect_custom_order_parties()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if (new.customer_id is distinct from old.customer_id
      or new.artisan_id is distinct from old.artisan_id)
     and (select auth.uid()) is not null
     and not public.is_admin() then
    raise exception 'Custom order participants cannot be reassigned';
  end if;

  return new;
end;
$$;

create trigger custom_orders_protect_parties
  before update on public.custom_orders
  for each row execute function public.protect_custom_order_parties();

create table public.custom_order_events (
  id uuid primary key default gen_random_uuid(),
  custom_order_id uuid not null references public.custom_orders (id) on delete cascade,
  status public.custom_order_status not null,
  note text,
  actor_id uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now()
);

create index custom_order_events_order_idx
  on public.custom_order_events (custom_order_id, created_at);

-- -----------------------------------------------------------------------------
-- Reviews
-- -----------------------------------------------------------------------------
create table public.reviews (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null references public.products (id) on delete cascade,
  customer_id uuid not null references public.profiles (id) on delete cascade,
  order_item_id uuid unique references public.order_items (id) on delete set null,
  rating smallint not null,
  title text,
  comment text not null,
  status public.review_status not null default 'pending',
  is_verified_purchase boolean not null default false,
  flagged_reason text,
  admin_note text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint reviews_rating_range check (rating between 1 and 5),
  constraint reviews_one_per_customer_product unique (customer_id, product_id)
);

create index reviews_product_idx on public.reviews (product_id, status);
create index reviews_customer_idx on public.reviews (customer_id);
create index reviews_status_idx on public.reviews (status);

create trigger reviews_set_updated_at
  before update on public.reviews
  for each row execute function public.set_updated_at();

-- -----------------------------------------------------------------------------
-- Cart & wishlist
-- -----------------------------------------------------------------------------
create table public.carts (
  id uuid primary key default gen_random_uuid(),
  profile_id uuid not null unique references public.profiles (id) on delete cascade,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create trigger carts_set_updated_at
  before update on public.carts
  for each row execute function public.set_updated_at();

create table public.cart_items (
  id uuid primary key default gen_random_uuid(),
  cart_id uuid not null references public.carts (id) on delete cascade,
  product_id uuid not null references public.products (id) on delete cascade,
  quantity integer not null default 1,
  gift_wrap boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint cart_items_quantity_positive check (quantity > 0),
  constraint cart_items_cart_product_key unique (cart_id, product_id)
);

create index cart_items_cart_idx on public.cart_items (cart_id);

create trigger cart_items_set_updated_at
  before update on public.cart_items
  for each row execute function public.set_updated_at();

create table public.wishlists (
  profile_id uuid not null references public.profiles (id) on delete cascade,
  product_id uuid not null references public.products (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (profile_id, product_id)
);

create index wishlists_product_idx on public.wishlists (product_id);

-- -----------------------------------------------------------------------------
-- Admin audit trail
-- -----------------------------------------------------------------------------
create table public.admin_actions (
  id uuid primary key default gen_random_uuid(),
  admin_id uuid not null references public.profiles (id) on delete restrict,
  action text not null,
  entity_type text not null,
  entity_id uuid,
  details jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

create index admin_actions_admin_idx on public.admin_actions (admin_id, created_at desc);
create index admin_actions_entity_idx on public.admin_actions (entity_type, entity_id);

-- -----------------------------------------------------------------------------
-- Ownership helpers (defined after their tables so SQL bodies can bind)
-- -----------------------------------------------------------------------------
create or replace function public.owns_artisan(target_artisan_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.artisans a
    where a.id = target_artisan_id
      and a.profile_id = (select auth.uid())
  );
$$;

create or replace function public.can_manage_product(target_product_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select public.is_admin() or exists (
    select 1
    from public.products p
    join public.artisans a on a.id = p.artisan_id
    where p.id = target_product_id
      and a.profile_id = (select auth.uid())
  );
$$;
